{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Acarbose mean systemic availability in healthy volunteers was 0.7–1.6% after oral versus intravenous administration, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Pentosan polysulfate sodium bioavailability was 0.5–1% after daily oral dosing of 400 mg in healthy subjects, indicating very low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Furosemide acyl glucuronide oral bioavailability was 0.15 ± 0.04 in humans, corresponding to 15% and below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Dextran sulfate was reported to have poor oral bioavailability, making it not practically valuable as an oral agent.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Baicalin has minimal oral bioavailability due to poor solubility and low permeability, consistent with low systemic exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All available experimental records from related molecules report oral bioavailability well below 20%, including acarbose (<2%), pentosan polysulfate (≤3%), furosemide acyl glucuronide (15%), dextran sulfate (poor), and baicalin (minimal). The consistent low-F evidence supports a low bioavailability prediction.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement is available for the query molecule.",
    "The query structure and physicochemical properties are not provided, limiting assessment of structural similarity to the low-F reference molecules.",
    "No high-bioavailability comparator evidence was available to challenge the low-F direction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

